package org.apache.commons.csv;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Iterator;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class CSVRecord_get_TriageGen2Test {

    @Mock
    private Map<String, Integer> mapping;

    @Mock
    private CSVRecord csvRecord;

    /**
     * Since CSVRecord is a complex class and the provided method relies on internal 
     * fields 'mapping' and 'values', we simulate the behavior using a spy or 
     * by assuming the internal state as described in the logic provided.
     * 
     * However, to strictly follow the provided method logic for testing:
     */

    @Test(expected = IllegalStateException.class)
    public void testGet_ThrowsExceptionWhenMappingIsNull() throws Exception {
        // We use reflection to simulate the private state of CSVRecord 
        // because the provided code snippet shows a dependency on an internal 'mapping' field.
        CSVRecord record = createRecordWithInternalState(null, new String[]{"val1"});
        record.get("anyName");
    }

    @Test
    public void testGet_ReturnsValueWhenNameExistsInMapping() throws Exception {
        String[] values = {"apple", "banana", "cherry"};
        Map<String, Integer> mockMapping = org.mockito.Mockito.mock(Map.class);
        when(mockMapping.get("banana")).thenReturn(1);

        CSVRecord record = createRecordWithInternalState(mockMapping, values);

        String result = record.get("banana");
        assertEquals("banana", result);
    }

    @Test
    public void testGet_ReturnsNullWhenNameDoesNotExistInMapping() throws Exception {
        String[] values = {"apple", "banana"};
        Map<String, Integer> mockMapping = org.mockito.Mockito.mock(Map.class);
        when(mockMapping.get("unknown")).thenReturn(null);

        CSVRecord record = createRecordWithInternalState(mockMapping, values);

        String result = record.get("unknown");
        assertNull(result);
    }

    /**
     * Helper method to instantiate CSVRecord and inject private fields 
     * 'mapping' and 'values' via reflection to satisfy the logic of the method under test.
     */
    private CSVRecord createRecordWithInternalState(Map<String, Integer> mapping, String[] values) throws Exception {
        // CSVRecord is typically instantiated via a Parser, but for unit testing 
        // the specific logic provided, we inject the fields.
        CSVRecord record = org.mockito.Mockito.spy(org.apache.commons.csv.CSVRecord.class);

        java.lang.reflect.Field mappingField = CSVRecord.class.getDeclaredField("mapping");
        mappingField.setAccessible(true);
        mappingField.set(record, mapping);

        java.lang.reflect.Field valuesField = CSVRecord.class.getDeclaredField("values");
        valuesField.setAccessible(true);
        valuesField.set(record, values);

        return record;
    }
}
